// The day's affirmation in Arabic, for the country pages in Arabic. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"لستِ مضطرة لإنجاز كل شيء اليوم. تكفي الخطوة الصغيرة التالية.\", \"التعب ليس فشلًا. أنتِ متعبة لأنكِ حاضرة كل يوم.\", \"الصحون يمكنها الانتظار. من حقكِ أن تجلسي خمس دقائق.\", \"رقائق الحبوب على العشاء تُحسب أيضًا إطعامًا لعائلتكِ.\", \"الراحة ليست شيئًا عليكِ أن تستحقيه. يمكنكِ أن ترتاحي الآن.\", \"في بعض الأيام يكون الإنجاز أن الجميع وصلوا إلى وقت النوم بسلام. وهذا إنجاز حقيقي.\", \"أنتِ تفعلين أكثر مما يراه أي أحد. أنا أرى ذلك.\", \"بيت غير مرتب وأطفال محبوبون. إنها مقايضة جيدة.\", \"في اليوم الصعب يبدو أفضل ما لديكِ مختلفًا، ومع ذلك فهو يُحسب.\", \"نفس عميق واحد. أرخي كتفيكِ. أنتِ بخير.\", \"لا بأس أن تخففي سقف توقعاتكِ اليوم. يمكنكِ رفعه من جديد في يوم آخر.\", \"طلب المساعدة قوة، وليس ضعفًا.\", \"من حقكِ أن تقولي لا لأمر إضافي.\", \"إن شعرتِ بالوحدة اليوم، فلستِ الأم الوحيدة التي شعرت بذلك. نحن كثيرات.\", \"تستحقين صديقة تسألكِ عن حالكِ وتنتظر الجواب.\", \"لا بأس أن تبادري أنتِ أولًا. معظم الأمهات يتمنين أن يبادر أحد.\", \"شعوركِ بأن لا أحد يراكِ لا يعني أنكِ غير مهمة. أنتِ مهمة جدًا.\", \"مشاعركِ مفهومة. أنتِ لستِ عبئًا.\", \"هنا لا تحتاجين إلى شرح يومكِ الصعب. نحن نفهمكِ.\", \"رسالة إلى أم أخرى تقول «وأنا أيضًا» قد تغيّر يومًا كاملًا.\", \"إرضاع، وتغيير، وهدهدة، ثم من جديد. هذا عمل حقيقي، حتى لو بدا كأنكِ جالسة فقط.\", \"أنتِ وطفلكِ ما زلتما تتعرفان على بعضكما. لا داعي للعجلة.\", \"الأيام مع المولود الجديد طويلة. هذه المرحلة لن تدوم إلى الأبد.\", \"إن كان كل ما فعلتِه اليوم أنكِ أبقيتِ إنسانًا صغيرًا شبعانَ ودافئًا، فقد قمتِ بعمل عظيم.\", \"لا يلزمكِ أن تعودي كما كنتِ بسرعة. يمكنكِ ببساطة أن تكوني حيث أنتِ.\", \"أيًّا كانت طريقة إطعام طفلكِ، فأنتِ تعتنين به. وهذا ما يهم.\", \"يمكن أن تكوني قليلة النوم ومليئة بالحب في الوقت نفسه.\", \"احضني طفلكِ ودعي شؤون البيت. البيت سيبقى في مكانه.\", \"نوبة غضب في المتجر لا تجعلكِ أمًّا سيئة. إنها تعني فقط أن لديكِ طفلًا صغيرًا.\", \"الصغار يختبرون الحدود لأنهم يشعرون بالأمان معكِ.\", \"بقيتِ هادئة دقيقة أطول من الأمس. وهذا يُحسب.\", \"إن فقدتِ أعصابكِ، فإن حضنًا وكلمة «آسفة» يصلحان الكثير. ويعلّمانهم شيئًا جميلًا أيضًا.\", \"أيدٍ لزجة، وأصوات عالية، ومشاعر كبيرة. أنتِ تربّين إنسانًا كاملًا.\", \"«لماذا؟» الخامسة في هذه الساعة هي عقل صغير ينمو.\", \"لا تحتاجين إلى يوم مثالي لتصنعي ذكرى سعيدة.\", \"باب يُصفق بقوة ليس نهاية الحكاية. اتركي الضوء مضاءً.\", \"قد لا يقولها ابنكِ المراهق، لكن وجودكِ الثابت يعني له الكثير.\", \"أن تكوني الهادئة في البيت عمل شاق. وأنتِ تقومين به.\", \"بعض أجمل الأحاديث تحدث في السيارة. واصلي القيادة.\", \"إنهم يبتعدون ليكبروا، لا ليتركوكِ خلفهم.\", \"لا تحتاجين إلى كل الإجابات. الإصغاء جزء كبير من الأمر.\", \"الأبناء الكبار ما زالوا يحتاجونكِ، لكن بطرق أهدأ.\", \"أن تحملي كل شيء وحدكِ يتطلب قوة لا يراها معظم الناس.\", \"أنتِ أمٌّ كافية لطفلكِ. وكنتِ كذلك دائمًا.\", \"يدان اثنتان ومئة مهمة. ترفّقي بنفسكِ.\", \"أطفالكِ يتعلمون، وهم يرونكِ، كيف يبدو الإنسان القوي المحب.\", \"أخذ استراحة ليس تخليًا عن موقعكِ. إنه ما يعينكِ على الاستمرار.\", \"لا أحد يعدّ النقاط. المهم هو الحب وأن تكوني حاضرة.\", \"الحزن والحب ينبعان من المكان نفسه. اشتياقكِ يدل على مقدار حبكِ.\", \"لا يوجد موعد صحيح لانتهاء الحزن. خذي الوقت الذي تحتاجينه.\", \"في الذكريات السنوية الصعبة، كوني رفيقة بنفسكِ كما تكونين مع صديقة.\", \"يمكنكِ أن تحملي الحزن وتضحكي مع أطفالكِ رغم ذلك. كلاهما حقيقي.\", \"إن فقدتِ حملًا أو طفلًا، فهذه خسارة حقيقية، وحبكِ حقيقي أيضًا.\", \"في بعض الأيام يكون الحزن صامتًا، وفي أيام أخرى يكون صاخبًا. وكلاهما طبيعي.\", \"قلة المال لا تعني قلة الحب.\", \"سيتذكر أطفالكِ الوقت الذي قضوه معكِ أكثر من الأشياء التي اشتريتِها.\", \"السؤال عن مساعدة في دفع الفواتير تصرف ذكي، وليس عيبًا. لهذا وُجدت المساعدة.\", \"عصر مجاني في الحديقة قد يكون أجمل يوم في الأسبوع.\", \"جعلتِ المال يكفي أسبوعًا آخر. هذا يحتاج إلى مهارة حقيقية.\", \"القلق بشأن المال مُتعب. أنتِ تحملين الكثير، وما زلتِ هنا.\", \"شربتِ كوبًا من الماء اليوم. ابدئي من هنا.\", \"خرج الجميع من الباب. ربما لم تكن الأحذية متطابقة. ومع ذلك إنجاز.\", \"أجريتِ المكالمة التي كنتِ تخشينها. كان ذلك شجاعة.\", \"ضحكتِ اليوم. تمسّكي بذلك.\", \"وجبة دافئة، وقميص نظيف، وحكاية قبل النوم. الأشياء الصغيرة تصنع طفولة.\", \"كنتِ لطيفة مع أحدهم اليوم، حتى لو كان ذلك مع نفسكِ فقط.\", \"التقدم لا الكمال. لقد تقدمتِ اليوم.\", \"أنهيتِ أمرًا واحدًا من القائمة. هذا أكثر من لا شيء.\", \"أنتِ أم جيدة. وقلقكِ بشأن ذلك يدل على مدى اهتمامكِ.\", \"أنتِ أكبر من كل ما تنجزينه في يوم واحد.\", \"أطفالكِ لا يحتاجون إلى أم مثالية. يحتاجونكِ أنتِ، وأنتِ معهم.\", \"كوني صبورة مع نفسكِ كما تصبرين على أطفالكِ.\", \"من حقكِ أن يكون لكِ مكان، وأن تريدي أشياء، وأن تكون لكِ أحلامكِ الخاصة.\", \"الخطأ لا يمحو الحب. الغد بداية جديدة.\", \"أنتِ العالم كله لأحدهم، وأنتِ أيضًا إنسانة قائمة بذاتها.\", \"لا بأس ألا تستمتعي بكل دقيقة. ما زال بإمكانكِ أن تحبي أطفالكِ من كل قلبكِ.\", \"لا توجد طريقة واحدة صحيحة لتكوني أمًّا. طريقتكِ مقبولة أيضًا.\", \"كما في وضعية الشجرة، لا بأس أن تتمايلي. يمكنكِ أن تستعيدي توازنكِ.\", \"ثبّتي قدميكِ كما في وضعية الجبل. أنتِ أثبت مما تشعرين.\", \"المحاربة الثانية: ساقان قويتان وذراعان مفتوحتان. هذه أنتِ في مواجهة هذا الأسبوع.\", \"شهيق حتى أربعة، وزفير حتى أربعة. أنتِ هنا، وأنتِ بخير.\", \"تمدّدي واسعة كالنجمة. من حقكِ أن تأخذي مساحتكِ.\", \"القرفصاء الواسعة المنخفضة صعبة الثبات. وكذلك اليوم الطويل. وأنتِ صامدة.\", \"يمكنكِ أن تميلي كالهلال وتبقي واقفة.\", \"لا يلزمكِ أن تلمسي أصابع قدميكِ بعد. كل قدر من التمدد يُحسب.\", \"وضعية المثلث: يد إلى الأسفل ويد إلى الأعلى. ابقي ثابتة وواصلي الامتداد.\", \"لقد تأخر الوقت. ما لم يُنجز اليوم يمكنه أن ينتظر حتى الغد.\", \"مستيقظة مع طفلكِ في هذه الساعة؟ أمهات كثيرات مستيقظات معكِ الآن.\", \"البيت هادئ. هذه اللحظة لكِ. تنفّسي.\", \"لقد اجتزتِ هذا اليوم. وهذا كل ما احتاجه اليوم.\", \"إن كان عقلكِ مشغولًا الليلة، فاكتبي ما فيه ودعيه ينتظر حتى الصباح.\", \"أريحي عينيكِ. غدًا يمكنكِ أن تبدئي من جديد.\", \"المناسبات قد تكون صعبة بقدر ما هي سعيدة. أيًّا كان شعوركِ في هذا الموسم، فلا بأس.\", \"المائدة لا تحتاج إلى أن تكون مثالية. المهم هم الناس الذين حولها.\", \"إن كنتِ تفتقدين أحدًا على المائدة هذا العام، فترفّقي بقلبكِ.\", \"شكرًا يا أمي، على كل وجبة، وكل مشوار، وكل حضن.\", \"لستِ مضطرة للاستضافة أو الخَبز أو الابتسام طوال الوقت. المناسبة البسيطة تبقى مناسبة.\", \"أجمل هدية يحصل عليها أطفالكِ هذا العام هي الوقت معكِ.\", \"الاحتفال الصغير مليء بالحب أيضًا. لا يحتاج إلى مال كثير ليكون مميزًا.\", \"أيام باردة وأحضان دافئة. أنتِ الركن الدافئ في بيتكِ.\", \"لا بأس أن تتجاوزي بعض صخب المناسبات. السكينة هدية أيضًا.\", \"إن كان هذا الموسم ثقيلًا عليكِ هذا العام، فلستِ وحدكِ. يومًا بيوم.\"]";D.body.appendChild(e)})();
